   100	/**
   101	 * Get canonical source key
   102	 * @param {string} source - Source value from event
   103	 * @returns {string} Canonical source key
   104	 */
   105	function normalizeSource(source) {
   106	  if (!source) return 'unknown';
   107	  const normalized = source.toLowerCase().trim();
   108	  return SOURCE_ALIAS_MAP[normalized] || normalized;
   109	}
