   111	/**
   112	 * Get source metadata for frontend dropdown
   113	 * @returns {Array} Array of { key, label, type } objects
   114	 */
   115	function getSourcesMetadata() {
   116	  return Object.entries(CANONICAL_SOURCES).map(([key, meta]) => ({
   117	    key,
   118	    label: meta.label,
   119	    type: meta.type,
   120	  }));
   121	}
   122	
   123	/**
   124	 * Normalize event source to canonical key
   125	 * @param {Object} event - Event object
   126	 * @returns {Object} Event with normalized source
   127	 */
   128	function normalizeEvent(event) {
   129	  return {
   130	    ...event,
   131	    source: normalizeSource(event.source),
   132	  };
   133	}
