   135	/**
   136	 * Proxy Ticketmaster API requests
   137	 */
   138	async function fetchTicketmasterEvents(city = 'Stockholm', countryCode = 'SE', size = 50) {
   139	  const url = `https://app.ticketmaster.com/discovery/v2/events.json?apikey=${TICKETMASTER_API_KEY}&city=${city}&countryCode=${countryCode}&size=${size}&sort=date,asc`;
   140	  
   141	  console.log(`[api] Fetching Ticketmaster events for ${city}...`);
   142	  
   143	  try {
   144	    const response = await axios.get(url, { timeout: 15000 });
   145	    
   146	    if (response.status !== 200) {
   147	      console.log(`[api] Ticketmaster returned ${response.status}`);
   148	      return { error: `HTTP ${response.status}`, events: [] };
   149	    }
   150	    
   151	    const data = response.data;
   152	    
   153	    if (!data._embedded || !data._embedded.events) {
   154	      console.log(`[api] No events found`);
   155	      return { events: [], count: 0 };
   156	    }
   157	    
   158	    const events = data._embedded.events.map(ev => ({
   159	      id: ev.id,
   160	      title: ev.name,
   161	      date: ev.dates?.start?.localDate || '',
   162	      time: ev.dates?.start?.localTime ? ev.dates.start.localTime.substring(0, 5) : '',
   163	      venue: ev._embedded?.venues?.[0]?.name || 'Unknown',
   164	      area: ev._embedded?.venues?.[0]?.city?.name || city,
   165	      description: ev.info || ev.pleaseNote || '',
   166	      url: ev.url || '',
   167	      source: 'ticketmaster',
   168	      imageUrl: ev.images?.[0]?.url || null,
   169	      priceRanges: ev.priceRanges || [],
   170	    }));
   171	    
   172	    console.log(`[api] Ticketmaster: ${events.length} events`);
   173	    return { events, count: events.length };
   174	  } catch (error) {
   175	    console.error(`[api] Ticketmaster error: ${error.message}`);
   176	    return { error: error.message, events: [] };
   177	  }
   178	}
