   180	/**
   181	 * Fetch from other sources directly (they don't need API keys)
   182	 */
   183	async function fetchOtherSources() {
   184	  const results = { sources: {} };
   185	  
   186	  // Kulturhuset Elasticsearch
   187	  try {
   188	    const esResp = await axios.post(
   189	      'https://elastic.kulturhusetstadsteatern.se/khst-events/_search',
   190	      {
   191	        size: 20,
   192	        query: { bool: { must: [{ range: { tixStartDate: { gte: 'now' } } }] } },
   193	        sort: [{ tixStartDate: { order: 'asc' } }],
   194	      },
   195	      { timeout: 10000, headers: { 'Content-Type': 'application/json' } }
   196	    );
   197	    
   198	    if (esResp.data?.hits?.hits) {
   199	      results.sources.kulturhuset = esResp.data.hits.hits.map(h => ({
   200	        id: h._id,
   201	        title: h._source?.drupalTitle || h._source?.tixName || 'Untitled',
   202	        date: (h._source?.tixStartDate || '').split('T')[0],
   203	        source: 'kulturhuset',
   204	      }));
   205	    }
   206	  } catch (e) {
   207	    console.log(`[api] Kulturhuset: ${e.message}`);
   208	  }
   209	  
   210	  // Malmö Live API
   211	  try {
   212	    const malmoResp = await axios.get('https://malmolive.se/api/events', { timeout: 10000 });
   213	    if (Array.isArray(malmoResp.data)) {
   214	      results.sources.malmolive = malmoResp.data.slice(0, 20).map(e => ({
   215	        id: e.tessitura_event_id || e.id,
   216	        title: e.title || e.name || 'Untitled',
   217	        date: (e.field_date_time || '').split('T')[0],
   218	        source: 'malmolive',
   219	      }));
   220	    }
   221	  } catch (e) {
   222	    console.log(`[api] Malmö Live: ${e.message}`);
   223	  }
   224	  
   225	  return results;
   226	}
