   231	async function handleEvents(req, res) {
   232	  const url = new URL(req.url, `http://localhost:${PORT}`);
   233	  const city = url.searchParams.get('city') || 'Stockholm';
   234	  const size = parseInt(url.searchParams.get('size') || '50');
   235	  
   236	  const ticketmaster = await fetchTicketmasterEvents(city, 'SE', size);
   237	  const otherSources = await fetchOtherSources();
   238	  
   239	  // Normalize all event sources to canonical keys
   240	  const normalizedTicketmaster = {
   241	    ...ticketmaster,
   242	    events: ticketmaster.events.map(normalizeEvent),
   243	  };
   244	  
   245	  const normalizedOtherSources = {
   246	    sources: {},
   247	  };
   248	  
   249	  // Normalize Kulturhuset events
   250	  if (otherSources.sources.kulturhuset) {
   251	    normalizedOtherSources.sources.kulturhuset = otherSources.sources.kulturhuset.map(normalizeEvent);
   252	  }
   253	  
   254	  // Normalize Malmö Live events (will become 'malmo-live' after normalization)
   255	  if (otherSources.sources.malmolive) {
   256	    normalizedOtherSources.sources.malmolive = otherSources.sources.malmolive.map(normalizeEvent);
   257	  }
   258	  
   259	  // Collect all available sources (for frontend dropdown)
   260	  const availableSources = new Set();
   261	  normalizedTicketmaster.events.forEach(e => availableSources.add(e.source));
   262	  Object.values(normalizedOtherSources.sources).forEach(events => {
   263	    events.forEach(e => availableSources.add(e.source));
   264	  });
   265	  
   266	  // Build sources metadata for dropdown (only include sources that have events)
   267	  const sources = getSourcesMetadata().filter(s => availableSources.has(s.key));
   268	  
   269	  const response = {
   270	    timestamp: new Date().toISOString(),
   271	    ticketmaster: normalizedTicketmaster,
   272	    otherSources: normalizedOtherSources,
   273	    sources: sources,
   274	    totalEvents: ticketmaster.count + 
   275	      (otherSources.sources.kulturhuset?.length || 0) +
   276	      (otherSources.sources.malmolive?.length || 0),
   277	  };
   278	  
   279	  res.writeHead(200, { 
   280	    'Content-Type': 'application/json',
   281	    'Access-Control-Allow-Origin': '*',
   282	  });
   283	  res.end(JSON.stringify(response, null, 2));
   284	}
